import { defineEntity, p, type InferEntity } from "@mikro-orm/core";

import { ReturnRequestSchema } from "../returns/return-request.entity";

/**
 * Customer evidence images (transport damage, missing items). Files are immutable: there is no update path except the
 * one-time attach (`return_request_id` from null to a request). `data` is the re-encoded image; unscanned or
 * unsanitized bytes are never stored.
 */
export const EvidenceFileSchema = defineEntity({
  name: "EvidenceFile",
  tableName: "evidence_files",
  properties: {
    // Random UUID generated by the repository: unguessable, never a sequence.
    id: p.uuid().primary(),
    orderNumber: p.string().length(100),
    // Null while the file is staged (uploaded, not yet attached to a request).
    returnRequest: () => p.manyToOne(ReturnRequestSchema).deleteRule("restrict").nullable(),
    contentType: p.string().length(16),
    byteSize: p.integer(),
    sha256: p.string().length(64).columnType("char(64)"),
    label: p.string().length(120),
    data: p.blob().columnType("bytea").lazy(),
    createdAt: p.datetime().onCreate(() => new Date()),
  },
  indexes: [{ name: "evidence_files_order_number_index", properties: ["orderNumber"] }],
});

export type EvidenceFileEntity = InferEntity<typeof EvidenceFileSchema>;
